{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "취약계층 반려동물 돌봄 지원 신청 자격에 서울 주민등록만 있으면 되는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울 주민등록만으로는 충분하지 않다. 조례 제25조의2 제4항에 따르면 경비를 지원받으려는 사람은 시에 주민등록을 두고 있어야 하고, 동물정보시스템에 등록된 해당 반려동물의 소유자등이어야 한다. 따라서 서울 주민등록 외에 동물정보시스템에 등록된 반려동물의 소유자등이라는 요건도 함께 충족해야 한다.",
          "b_ids": "동물보호:제25조의2제4항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "취약계층 반려동물 돌봄 지원을 아무 동물병원에서나 받을 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "아무 동물병원에서나 받을 수 없다. 조례 제25조의2 제3항에 따르면 제2항에 따른 경비는 시장 또는 구청장이 지정하거나 협약을 체결한 동물병원 등의 기관에만 지원할 수 있다. 따라서 시장 또는 구청장이 지정하거나 협약을 체결한 동물병원 등의 기관에서 지원을 받아야 한다.",
          "b_ids": "동물보호:제25조의2제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
